// The live segmenter, ported from `src/v2m/core/liveseg.py`.
//
// This file is a COPY of a measured state machine, and it is only worth
// having if it decides the same notes: `web/test/cases.json` is generated by
// driving the Python class over the trap families (a glide, a same-pitch
// re-attack, a mute run, a borderline plateau, a flush merge) and
// `web/test/segmenter.test.mjs` replays every case here. Change liveseg.py
// and that JSON goes stale — `tests/test_web_build.py` fails until both
// sides are regenerated together.
//
// Two JavaScript differences matter and are handled explicitly:
//  - `Math.round` breaks ties toward +Infinity while Python's `round` breaks
//    them toward even (`round(60.5) == 60`), so `pyRound` is used wherever a
//    note's MIDI number is decided;
//  - `median` of an even count is the mean of the two middle values, as
//    numpy's does.

import { AttackTracker } from "./attacks.js";
import {
  A4_HZ,
  BREAKOUT_ST,
  CLEAN_FRAMES,
  HOLD_RAW_FRAMES,
  HOLD_ST,
  LIVE_DOUBT_PERIODICITY,
  MEMORY_S,
  MIN_GAP_HOLD_S,
  NOTE_NAMES,
  PIANO_MAX_MIDI,
  PIANO_MIN_MIDI,
  REARTIC_ST,
  SPLIT_FRAMES,
  STAGE_MAX_S,
  WEAK_RATIO,
} from "./constants.js";
import { HOP_MS, MIN_PITCH_QUALITY, WINDOW_MS, YinBlock } from "./yin.js";

// The port's values live in the generated `constants.js` — one declaration
// read from liveseg.py and music.py, so a widening or a renamed note spelling
// cannot survive on one side. Re-exported here because this module is where
// their readers already look.
export {
  A4_HZ,
  BREAKOUT_ST,
  CLEAN_FRAMES,
  HOLD_RAW_FRAMES,
  HOLD_ST,
  LIVE_DOUBT_PERIODICITY,
  MEMORY_S,
  MIN_GAP_HOLD_S,
  NOTE_NAMES,
  PIANO_MAX_MIDI,
  PIANO_MIN_MIDI,
  REARTIC_ST,
  SPLIT_FRAMES,
  STAGE_MAX_S,
  WEAK_RATIO,
};

// Page-local sizes: they describe this port's buffers, not a decision
// threshold, so they have no Python twin to follow.
export const MAX_ATTACKS = 64;
export const SPLIT_FRAME_S = 256 / 22050;
export const WEAK_PEEK_SLICES = 16;

export const hzToMidi = (hz) => 69.0 + 12.0 * Math.log2(hz / A4_HZ);
export const onPiano = (midi) => midi >= PIANO_MIN_MIDI && midi <= PIANO_MAX_MIDI;

export function midiToName(midi) {
  const value = Math.round(midi);
  return `${NOTE_NAMES[((value % 12) + 12) % 12]}${Math.floor(value / 12) - 1}`;
}

export function median(values) {
  const sorted = Array.from(values).sort((a, b) => a - b);
  const mid = sorted.length >> 1;
  if (!sorted.length) return NaN;
  return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
}

/** Python's `round`: ties go to the even neighbour, not to +Infinity. */
export function pyRound(x) {
  const floor = Math.floor(x);
  const diff = x - floor;
  if (diff > 0.5) return floor + 1;
  if (diff < 0.5) return floor;
  return floor % 2 === 0 ? floor : floor + 1;
}

export class LiveNote {
  constructor({ start, end, midi, confidence = 0.9, articulated = false, strength = 0, dev = 0, voiceDoubt = false }) {
    this.start = start;
    this.end = end;
    this.midi = midi;
    this.confidence = confidence;
    this.articulated = articulated;
    this.strength = strength;
    this.dev = dev;
    this.voiceDoubt = voiceDoubt;
  }

  get duration() {
    return this.end - this.start;
  }
}

/**
 * IDLE -> PENDING -> ACTIVE, with the desktop's guards.
 * `push` returns "on", "off" or "".
 */
export class LiveNoteSegmenter {
  constructor({
    confirm_s = 0.09,
    release_s = 0.12,
    min_note_s = 0.1,
    semitones = 0.6,
    frame_s = SPLIT_FRAME_S,
  } = {}) {
    this.confirm_s = confirm_s;
    this.release_s = release_s;
    this.min_note_s = min_note_s;
    this.semitones = semitones;
    this.frame_s = frame_s;

    this.state = "IDLE";
    this.lastFrameT = null;
    this.pendingStart = null;
    this.pendingMidis = [];
    this.pendingTimes = [];
    this.pendingAttack = null;
    this.noteStart = null;
    this.noteMidis = [];
    this.notePeriodicity = [];
    this.notePitch = null;
    this.lastVoicedT = null;
    this.lastHz = NaN;
    this.notes = [];
    this.attacks = [];
    this.noteArticulated = false;
    this.noteStrength = 0;
    this.pendingStrength = 0;
    this.recentMidis = [];
    this.recentRaw = [];
    this.voicedBreak = false;
    this.breakCutT = null;
    this.stagedAttack = null;
    this.stagedStrength = 0;
  }

  push(t, hz, { attack = false, strength = 0, weak = false, quality = NaN } = {}) {
    this.lastFrameT = t;
    let ev = "";
    if (attack) {
      this.attacks.push(t);
      if (this.attacks.length > MAX_ATTACKS) this.attacks.splice(0, this.attacks.length - MAX_ATTACKS);
    }
    const voiced = Number.isFinite(hz) && hz > 0;

    if (!voiced) {
      // An attack can land on a MUTE frame (the consonant of the re-attacked
      // note): stage it for the next voiced frame instead of swallowing it.
      if (attack && this.state === "ACTIVE") {
        this.stagedAttack = t;
        this.stagedStrength = strength;
      } else if (attack && this.state === "IDLE") {
        this.stagedAttack = t;
        this.stagedStrength = strength;
      }
      if (this.state === "ACTIVE") {
        if (!this.voicedBreak) this.breakCutT = this.lastVoicedT;
        this.voicedBreak = true;
      } else if (this.state === "PENDING") {
        if (this.pendingAttack !== null) {
          this.stagedAttack = this.pendingAttack;
          this.stagedStrength = this.pendingStrength;
        } else if (attack) {
          this.stagedAttack = t;
          this.stagedStrength = strength;
        }
        this.resetPending();
      }
      if (this.state === "ACTIVE" && this.lastVoicedT !== null) {
        if (t - this.lastVoicedT >= MIN_GAP_HOLD_S) {
          this.closeNote(this.lastVoicedT);
          ev = "off";
        }
      }
      return ev;
    }

    this.lastHz = hz;
    const rawMidi = hzToMidi(hz);
    const m = this.clean(rawMidi);

    if (
      attack &&
      this.state === "ACTIVE" &&
      this.noteStart !== null &&
      t - this.noteStart >= this.min_note_s
    ) {
      if (this.voicedBreak) {
        if (this.splitSamePitch(t, rawMidi, strength)) ev = "off";
        else {
          this.stagedAttack = t;
          this.stagedStrength = strength;
        }
      } else {
        this.closeNote(t);
        ev = "off";
      }
    } else if (this.stagedAttack !== null && this.state === "ACTIVE") {
      const staged = this.stagedAttack;
      const stagedStrength = this.stagedStrength;
      this.stagedAttack = null;
      this.stagedStrength = 0;
      this.closeNote(staged);
      this.startPending(staged, m, staged, stagedStrength);
      ev = "off";
    }
    if (this.stagedAttack !== null && this.state === "IDLE") {
      // A stale stage (a breath 0.2 s before the phrase) is dropped rather
      // than pulling the onset back.
      if (t - this.stagedAttack <= STAGE_MAX_S) {
        const staged = this.stagedAttack;
        const stagedStrength = this.stagedStrength;
        this.stagedAttack = null;
        this.stagedStrength = 0;
        this.startPending(t, m, staged, stagedStrength);
      } else {
        this.stagedAttack = null;
        this.stagedStrength = 0;
      }
    } else if (this.stagedAttack !== null && this.state !== "ACTIVE") {
      this.stagedAttack = null;
      this.stagedStrength = 0;
    }

    if (this.state === "ACTIVE") {
      const ref = median(this.noteMidis);
      const confirmed = this.notePitch !== null ? this.notePitch : ref;
      if (Math.abs(rawMidi - confirmed) > BREAKOUT_ST && !this.voicedBreak) {
        this.breakCutT = this.lastVoicedT;
        this.voicedBreak = true;
      }
      if (weak) {
        if (!this.voicedBreak) this.breakCutT = this.lastVoicedT;
        this.voicedBreak = true;
      } else if (Math.abs(m - ref) <= this.semitones) {
        if (this.voicedBreak && this.splitSamePitch(t, rawMidi, 0)) {
          ev = "off";
        } else {
          this.noteMidis.push(m);
          if (Number.isFinite(quality)) this.notePeriodicity.push(quality);
          if (Math.abs(rawMidi - confirmed) <= BREAKOUT_ST) {
            this.voicedBreak = false;
            this.breakCutT = null;
          }
        }
      } else {
        this.closeNote(t);
        ev = "off";
        this.startPending(t, m);
        this.voicedBreak = false;
        this.breakCutT = null;
      }
    } else if (this.state === "IDLE") {
      if (!weak) this.startPending(t, m, attack ? t : null, strength);
    } else if (this.state === "PENDING") {
      this.extendPending(t, m, attack ? t : null, strength);
      const window = this.holdWindow(t);
      if (window !== null) {
        this.state = "ACTIVE";
        this.noteStart = this.pendingAttack !== null ? this.pendingAttack : window[0][0];
        this.noteArticulated = this.pendingAttack !== null;
        this.noteStrength = this.pendingStrength;
        this.noteMidis = window.map(([, mm]) => mm);
        // The pending window's frames are not kept: a doubt describes the
        // CONFIRMED plateau.
        this.notePeriodicity = [];
        this.notePitch = median(window.map(([, mm]) => mm));
        ev = "on";
      }
    }
    this.lastVoicedT = t;
    return ev;
  }

  splitSamePitch(t, raw, strength = 0) {
    if (this.noteStart === null || !this.noteMidis.length) return false;
    const cut = this.breakCutT !== null ? this.breakCutT : this.lastVoicedT;
    const ref = this.notePitch !== null ? this.notePitch : median(this.noteMidis);
    if (cut === null || Math.abs(raw - ref) > REARTIC_ST) return false;
    if (t - cut >= SPLIT_FRAMES * this.frame_s || cut - this.noteStart < this.min_note_s) return false;
    this.closeNote(cut);
    this.startPending(t, raw, cut, strength);
    this.voicedBreak = false;
    this.breakCutT = null;
    return true;
  }

  clean(m) {
    this.recentRaw.push(m);
    if (this.recentRaw.length > HOLD_RAW_FRAMES) this.recentRaw.shift();
    this.recentMidis.push(m);
    if (this.recentMidis.length > CLEAN_FRAMES) this.recentMidis.shift();
    return median(this.recentMidis);
  }

  startPending(t, m, attackT = null, strength = 0) {
    this.state = "PENDING";
    this.pendingStart = t;
    this.pendingMidis = [m];
    this.pendingTimes = [t];
    this.pendingAttack = attackT;
    this.pendingStrength = attackT !== null ? strength : 0;
  }

  extendPending(t, m, attackT = null, strength = 0) {
    const keep = [];
    for (let i = 0; i < this.pendingTimes.length; i++) {
      const tt = this.pendingTimes[i];
      if (t - tt <= MEMORY_S && tt >= t - this.confirm_s) keep.push(i);
    }
    this.pendingMidis = keep.map((i) => this.pendingMidis[i]);
    this.pendingTimes = keep.map((i) => this.pendingTimes[i]);
    this.pendingMidis.push(m);
    this.pendingTimes.push(t);
    if (attackT !== null && this.pendingAttack === null) {
      this.pendingAttack = attackT;
      this.pendingStrength = strength;
    } else if (attackT !== null && strength > this.pendingStrength) {
      this.pendingStrength = strength;
    }
    const trim = [];
    for (let i = 0; i < this.pendingTimes.length; i++) {
      const tt = this.pendingTimes[i];
      if (t - tt <= MEMORY_S && tt >= t - this.confirm_s) trim.push(i);
    }
    if (trim.length < this.pendingTimes.length) {
      this.pendingMidis = trim.map((i) => this.pendingMidis[i]);
      this.pendingTimes = trim.map((i) => this.pendingTimes[i]);
    }
  }

  /**
   * The last `confirm_s` of frames when the pitch held there, else null.
   * The hold must SPAN the window (a glide's tail never does) and the RAW
   * frames must be flat too: the 5-frame median rides a slow ramp.
   */
  holdWindow(t) {
    const window = [];
    for (let i = 0; i < this.pendingTimes.length; i++) {
      if (t - this.pendingTimes[i] <= this.confirm_s) {
        window.push([this.pendingTimes[i], this.pendingMidis[i]]);
      }
    }
    if (window.length < 3) return null;
    const hop = (window[window.length - 1][0] - window[0][0]) / (window.length - 1);
    if (t - window[0][0] < this.confirm_s - hop) return null;
    const pitches = window.map(([, mm]) => mm);
    if (Math.max(...pitches) - Math.min(...pitches) > HOLD_ST) return null;
    const raws = this.recentRaw.slice(-HOLD_RAW_FRAMES);
    if (raws.length >= HOLD_RAW_FRAMES) {
      if (Math.max(...raws) - Math.min(...raws) > HOLD_ST) return null;
    }
    return window;
  }

  resetPending() {
    this.state = "IDLE";
    this.pendingStart = null;
    this.pendingMidis = [];
    this.pendingTimes = [];
    this.pendingAttack = null;
  }

  closeNote(endT) {
    if (this.noteStart === null || !this.noteMidis.length) {
      this.resetPending();
      return;
    }
    const start = this.noteStart;
    let reference = this.notePitch;
    if (reference === null) reference = median(this.noteMidis);
    const midi = pyRound(reference);
    // Only piano keys make it into the take: a pitch outside is an octave
    // error or a breath, not a note the singer produced.
    if (endT - start >= this.min_note_s && onPiano(midi)) {
      const plateau = this.notePitch !== null ? this.notePitch : median(this.noteMidis);
      // Notes stay ORDERED and non-overlapping: the predecessor's end is
      // clamped to this start, and a zero-length predecessor is dropped.
      if (this.notes.length && this.notes[this.notes.length - 1].end > start) {
        const last = this.notes[this.notes.length - 1];
        if (start - last.start >= this.min_note_s) last.end = start;
        else this.notes.pop();
      }
      const periodicity = this.notePeriodicity.length ? median(this.notePeriodicity) : NaN;
      this.notes.push(
        new LiveNote({
          start,
          end: endT,
          midi,
          articulated: this.noteArticulated,
          strength: this.noteStrength,
          dev: Math.max(-0.5, Math.min(0.5, plateau - pyRound(plateau))),
          // PUBLISHED doubt: the note keeps its place, the roll says the
          // evidence was thin (never a reason to drop or move it).
          voiceDoubt: Number.isFinite(periodicity) && periodicity > LIVE_DOUBT_PERIODICITY,
        }),
      );
    }
    this.noteStart = null;
    this.noteMidis = [];
    this.notePeriodicity = [];
    this.notePitch = null;
    this.noteArticulated = false;
    this.noteStrength = 0;
    this.voicedBreak = false;
    this.breakCutT = null;
    this.resetPending();
  }

  activeNote(t) {
    if (this.state !== "ACTIVE" || this.noteStart === null || !this.noteMidis.length) return null;
    const midi = pyRound(median(this.noteMidis));
    if (!onPiano(midi)) return null;
    return new LiveNote({ start: this.noteStart, end: Math.max(t, this.noteStart + 0.05), midi });
  }

  current() {
    if (this.state === "ACTIVE" && this.noteMidis.length) {
      return { midi: median(this.noteMidis), hz: this.lastHz };
    }
    if (this.state === "PENDING" && this.pendingMidis.length) {
      return { midi: median(this.pendingMidis), hz: this.lastHz };
    }
    return null;
  }

  confirmed() {
    if (this.state !== "ACTIVE" || this.notePitch === null) return null;
    const midi = pyRound(this.notePitch);
    if (!onPiano(midi)) return null;
    return { midi, hz: this.lastHz };
  }

  recentMidi() {
    if (!this.recentMidis.length) return null;
    return median(this.recentMidis.slice(-CLEAN_FRAMES));
  }

  /** Force-close the current note and merge fragments (see liveseg.flush). */
  flush(t) {
    if (this.state === "ACTIVE") this.closeNote(this.lastVoicedT !== null ? this.lastVoicedT : t);
    const merged = [];
    for (const n of this.notes) {
      const last = merged[merged.length - 1];
      const gap = last ? n.start - last.end : 1.0;
      if (
        last &&
        !n.articulated &&
        n.midi === last.midi &&
        gap <= this.release_s &&
        (n.duration < this.min_note_s || last.duration < this.min_note_s || gap < MIN_GAP_HOLD_S)
      ) {
        last.end = n.end;
        last.confidence = Math.max(last.confidence, n.confidence);
        last.strength = Math.max(last.strength, n.strength);
      } else {
        merged.push(n);
      }
    }
    this.notes = merged;
  }
}

/**
 * Captured blocks -> pitch frames -> notes, with the attack evidence.
 * Same chain as `LivePitchStream`, expressed in TIME so a 44.1 or 48 kHz
 * device reads the same durations (ADR 0009).
 */
export class LivePitchStream {
  constructor(sr, { gateRms, windowMs = WINDOW_MS, hopMs = HOP_MS } = {}) {
    this.sr = sr;
    this.gateRms = gateRms;
    this.window = Math.max(64, Math.round((sr * windowMs) / 1000));
    this.hop = Math.max(64, Math.round((sr * hopMs) / 1000));
    this.frameS = this.hop / sr;
    this.yin = new YinBlock(sr, { window: this.window, hop: this.hop });
    this.attacks = new AttackTracker();
    this.seg = new LiveNoteSegmenter({ frame_s: this.frameS });
    this.attackPending = false;
    this.pendingStrength = 0;
    this.recentLevels = [];
  }

  /** One captured block; returns {level, frames}. */
  feed(block, t) {
    const x = block;
    const rms = AttackTracker.level(x);
    if (this.attacks.push(t, x)) {
      this.attackPending = true;
      this.pendingStrength = this.attacks.strength;
    }
    // The gate is ONE policy: a block under it is silence for the level
    // meter AND for the pitch (a sub-gate rumble is acoustically silence).
    const belowGate = rms < this.gateRms;
    const frames = [];
    for (const frame of this.yin.pushWithQuality(x)) {
      let hz = frame.hz;
      if (belowGate) hz = NaN;
      let weak = false;
      if (Number.isFinite(hz) && hz > 0) {
        // The frame's own hop slice: the seam of a re-emitted note straddles
        // capture blocks coarser than the hop it lives at.
        const center = Math.round(frame.t * this.sr);
        const blockStart = Math.round(t * this.sr) - x.length;
        const i0 = center - Math.floor(this.window / 2) - blockStart;
        const lo = Math.max(0, i0);
        const hi = Math.min(x.length, i0 + this.hop);
        if (hi > lo) {
          let acc = 0;
          for (let i = lo; i < hi; i++) acc += x[i] * x[i];
          const level = Math.sqrt(acc / (hi - lo));
          this.recentLevels.push(level);
          if (this.recentLevels.length > WEAK_PEEK_SLICES) this.recentLevels.shift();
          if (this.recentLevels.length >= 3) {
            weak = level < WEAK_RATIO * median(this.recentLevels);
          }
        }
      }
      this.seg.push(frame.t, hz, {
        attack: this.attackPending,
        strength: this.pendingStrength,
        weak,
        quality: frame.quality,
      });
      this.attackPending = false;
      this.pendingStrength = 0;
      frames.push({ t: frame.t, hz });
    }
    return { level: rms, frames };
  }
}
